    private static Map<String,Object> read(Path p,int max)throws IOException{return object(NextflowParameters.parse(NextflowFiles.utf8(NextflowFiles.bytes(p,max)),max,20000000));}
    private static byte[] resource(String name)throws IOException{try(var in=Rphenograph099WorkflowCli.class.getResourceAsStream(RESOURCE+name)){if(in==null)throw new IOException("Missing packaged resource: "+name);return in.readAllBytes();}}
    private record Stamp(long bytes,FileTime modified,Object key) { }
    private static Stamp stamp(Path p)throws IOException{var a=Files.readAttributes(p,BasicFileAttributes.class,LinkOption.NOFOLLOW_LINKS);require(a.isRegularFile(),"Input no longer a regular file");return new Stamp(a.size(),a.lastModifiedTime(),a.fileKey());}
    private static void same(Path p,NextflowFiles.Pin wanted)throws IOException{require(wanted.equals(NextflowFiles.pin(p,wanted.bytes(),()->{})),"Captured input/source/runtime changed: "+p);}
    private static void newOutput(Path out,List<Path> paths)throws IOException{require(!Files.exists(out,LinkOption.NOFOLLOW_LINKS),"Output must be NEW; retain prior evidence");NextflowFiles.directory(out.getParent());for(Path p:paths)require(!out.startsWith(p)&&!p.startsWith(out),"Output overlaps protected input/source/runtime");Files.createDirectory(out);}
